// The type files "Code Explainer: Add Widget Types" writes for widget authors (docs/WIDGETS-PLAN.md §2, §9),
// so `tsc` and IntelliSense work on widgets without installing packages. The .d.ts files here are shipped
// as they are; libraries.d.ts and lucide-react.d.ts are generated by scripts/widget-types.ts.

/** The declaration files, in this folder. */
export const WIDGET_TYPE_FILES = ['react.d.ts', 'explainer.d.ts', 'ui.d.ts', 'libraries.d.ts', 'lucide-react.d.ts'] as const;

/**
 * The `.explain/tsconfig.json` that goes with them. `typesDir` is where the declaration files are written,
 * relative to `.explain/` (for example `.types`).
 */
export function widgetTsconfig(typesDir: string): string {
  const config = {
    compilerOptions: {
      target: 'ES2022',
      lib: ['ES2022', 'DOM', 'DOM.Iterable'],
      module: 'ESNext',
      moduleResolution: 'Bundler',
      jsx: 'react-jsx',
      strict: true,
      noEmit: true,
      allowJs: true,
      checkJs: false,
      resolveJsonModule: true,
      esModuleInterop: true,
      allowSyntheticDefaultImports: true,
      isolatedModules: true,
      skipLibCheck: true,
      types: [],
      typeRoots: [],
    },
    include: [`${typesDir}/*.d.ts`, '*/**/*.tsx', '*/**/*.ts', '*/**/*.jsx'],
  };
  return `${JSON.stringify(config, null, 2)}\n`;
}
